12	export const useReactionGroups = (reactions: Reaction[]): ReactionGroup => {
13	  const creatorNames = useMemo(() => reactions.map((r) => r.creator), [reactions]);
14	  const { data: userMap } = useUsersByNames(creatorNames);
15	
16	  return useMemo(() => {
17	    const reactionGroup = new Map<string, User[]>();
18	    for (const reaction of reactions) {
19	      const user = userMap?.get(reaction.creator);
20	      if (!user) continue;
21	
22	      const users = reactionGroup.get(reaction.reactionType) || [];
23	      users.push(user);
24	      reactionGroup.set(reaction.reactionType, users);
25	    }
26	    return reactionGroup;
27	  }, [reactions, userMap]);
28	};
